 x0), dot(p1, x1), dot(p2, x2), dot(p3, x3)));\n}\n\nfn simplexFBM(x: vec3f, octaves: i32, freq_in: f32) -> f32 {\n\tvar final_: f32 = 0.0;\n\tvar denom: f32 = 0.0;\n\tvar amp: f32 = 1.0;\n\tvar freq = freq_in;\n\n\tfor (var i: i32 = 0; i < octaves; i++) {\n\t\tfinal_ += amp * simplexNoise(x * freq);\n\t\tdenom += amp;\n\n\t\tfreq *= 2.0;\n\t\tamp *= 0.5;\n\t}\n\n\treturn final_ / denom;\n}\n\nfn mod7v3(x: vec3f) -> vec3f { return x - floor(x * (1.0 / 7.0)) * 7.0; }\n\nfn permuteV3(x: vec3f) -> vec3f { return mod289v3((34.0 * x + 10.0) * x); }\n\nfn worleyNoise(P: vec3f) -> f32 {\n\tlet K = 0.142857142857;\n\tlet Ko = 0.428571428571;\n\tlet K2 = 0.020408163265306;\n\tlet Kz = 0.166666666667;\n\tlet Kzo = 0.416666666667;\n\tlet jitter = 1.0;\n\n\tlet Pi = mod289v3(floor(P));\n\tlet Pf = fract(P) - 0.5;\n\n\tlet Pfx = Pf.x + vec3f(1.0, 0.0, -1.0);\n\tlet Pfy = Pf.y + vec3f(1.0, 0.0, -1.0);\n\tlet Pfz = Pf.z + vec3f(1.0, 0.0, -1.0);\n\n\tlet p = permuteV3(Pi.x + vec3f(-1.0, 0.0, 1.0));\n\tlet p1 = permuteV3(p + Pi.y - 1.0);\n\tlet p2 = permuteV3(p + Pi.y);\n\tlet p3 = permuteV3(p + Pi.y + 1.0);\n\n\tlet p11 = permuteV3(p1 + Pi.z - 1.0);\n\tlet p12 = permuteV3(p1 + Pi.z);\n\tlet p13 = permuteV3(p1 + Pi.z + 1.0);\n\n\tlet p21 = permuteV3(p2 + Pi.z - 1.0);\n\tlet p22 = permuteV3(p2 + Pi.z);\n\tlet p23 = permuteV3(p2 + Pi.z + 1.0);\n\n\tlet p31 = permuteV3(p3 + Pi.z - 1.0);\n\tlet p32 = permuteV3(p3 + Pi.z);\n\tlet p33 = permuteV3(p3 + Pi.z + 1.0);\n\n\tlet ox11 = fract(p11 * K) - Ko;\n\tlet oy11 = mod7v3(floor(p11 * K)) * K - Ko;\n\tlet oz11 = floor(p11 * K2) * Kz - Kzo;\n\n\tlet ox12 = fract(p12 * K) - Ko;\n\tlet oy12 = mod7v3(floor(p12 * K)) * K - Ko;\n\tlet oz12 = floor(p12 * K2) * Kz - Kzo;\n\n\tlet ox13 = fract(p13 * K) - Ko;\n\tlet oy13 = mod7v3(floor(p13 * K)) * K - Ko;\n\tlet oz13 = floor(p13 * K2) * Kz - Kzo;\n\n\tlet ox21 = fract(p21 * K) - Ko;\n\tlet oy21 = mod7v3(floor(p21 * K)) * K - Ko;\n\tlet oz21 = floor(p21 * K2) * Kz - Kzo;\n\n\tlet ox22 = fract(p22 * K)