  uc = `\n\tlet atm = UnpackAtm(solarIrradiance, rayleighScattering, mieScattering,\n\t\tskySrtl, sunSrtl, atmScalars, muSMin);\n\n\tvar ctx: CloudsCtx;\n\tctx.maxDistance = cloudsParamsA.x;\n\tctx.sigmaS = cloudsParamsA.y;\n\tctx.sigmaA = cloudsParamsA.z;\n\tctx.cloudLayerThickness = cloudsParamsA.w;\n\tctx.cloudLayerBottom = cloudsParamsB.x;\n\tctx.highCloudsHeight = cloudsParamsB.y;\n\tctx.highCloudsScale = cloudsParamsB.z;\n\tctx.weatherMapScale = cloudsParamsB.w;\n\tctx.baseNoiseScale = cloudsParamsC.x;\n\tctx.detailNoiseScale = cloudsParamsC.y;\n\tctx.cirrusDensity = cloudsParamsC.z;\n\tctx.altoDensity = cloudsParamsC.w;\n\tctx.windSpeed = cloudsParamsD.x;\n\tctx.weatherMapBlend = cloudsParamsD.y;\n\tctx.time = cloudsParamsD.z;\n\tctx.minStep = cloudsParamsD.w;\n\tctx.sigmaT = ctx.sigmaA + ctx.sigmaS;\n\tctx.fogFactor = ctx.maxDistance / 6.0;\n\tctx.bottomRadius = atm.bottom_radius;\n\tctx.sunDir = normalize(sunDir);\n\tctx.earthCenter = vec3f(0.0, -atm.bottom_radius, 0.0);\n\n\tlet rd = SkyViewRay(uv, ray00, ray10, ray01, ray11);\n\n\tlet volumetric = RaymarchVolumetricCloud(ctx, atm,\n\t\ttransmittanceTex, scatteringTex, scatteringSamp, irradianceTex,\n\t\tbaseNoiseTex, noiseSamp, detailNoiseTex,\n\t\tweatherCurTex, weatherSamp, weatherNextTex,\n\t\tcameraPos, rd);\n\tlet hightAlt = HighAltitudeCloud(ctx, atm,\n\t\ttransmittanceTex, scatteringTex, scatteringSamp,\n\t\thighCloudsTex, weatherSamp,\n\t\tcameraPos, rd);\n\n\tvar cloud = volumetric;\n\tcloud = vec4f(cloud.rgb + (1.0 - cloud.a) * hightAlt.rgb,\n\t\tcloud.a + (1.0 - cloud.a) * hightAlt.a);\n\n\treturn vec4f(min(cloud.rgb, vec3f(${ic})), cloud.a);\n`,
